    required this.onNotificationsTap,
    required this.onProfileTap,
    required this.avatar,
    this.notificationCount = 0,
  }) : super(key: key);

  @override
  State<VigilArtHeaderBar> createState() => _VigilArtHeaderBarState();
}

const VigilArtHeaderBar({
