Widget _buildButtonContent(Color contentColor) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        if (showIcon && icon != null) ...[
          IconTheme(
            data: IconThemeData(
              color: contentColor,
              size: 20,
            ),
            child: icon!,
          ),
          const SizedBox(width: 8),
        ],
        Text(
          text,
          style: TextStyle(
            fontSize: 16,
            fontWeight: FontWeight.w600,
            color: contentColor,
          ),
        ),
      ],
    );
  }

